describe('Image Upload - Dimension Validation', () => {
  beforeEach(() => {
    cy.visit('/upload');
    cy.get('[data-testid="image-upload-input"]').as('uploadInput');
  });

  it('should display error message when image dimensions are too small', () => {
    const smallImagePath = 'cypress/fixtures/small-image.jpg';

    cy.get('@uploadInput').selectFile(smallImagePath, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Image dimensions are too small');

    cy.get('[data-testid="upload-button"]')
      .should('be.disabled');
  });

  it('should allow upload when image dimensions meet minimum requirements', () => {
    const validImagePath = 'cypress/fixtures/valid-image.jpg';

    cy.get('@uploadInput').selectFile(validImagePath, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('not.exist');

    cy.get('[data-testid="upload-button"]')
      .should('not.be.disabled')
      .click();

    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Image uploaded successfully');
  });

  it('should clear error message when user selects a valid image after invalid one', () => {
    const smallImagePath = 'cypress/fixtures/small-image.jpg';
    const validImagePath = 'cypress/fixtures/valid-image.jpg';

    cy.get('@uploadInput').selectFile(smallImagePath, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('be.visible');

    cy.get('@uploadInput').selectFile(validImagePath, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('not.exist');
  });

  it('should display specific error for extremely small dimensions', () => {
    const tinyImagePath = 'cypress/fixtures/tiny-image.jpg';

    cy.get('@uploadInput').selectFile(tinyImagePath, { force: true });

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Minimum dimensions required: 100x100px');
  });
});
